final class Locator(private val services: Map[Class[?], Any]) {
  def get[A](using ct: scala.reflect.ClassTag[A]): A =
    services.getOrElse(
      ct.runtimeClass,
      throw new NoSuchElementException(s"unregistered: ${ct.runtimeClass.getName}")
    ).asInstanceOf[A]
}

val locator = Locator(Map(classOf[Clock] -> SystemClock))
val clock = locator.get[Clock]
